    /**
     * Selects a collection of ClTransferencia objects pre-filled with their ClEstadoTransferencia objects.
     * @param      Criteria  $criteria
     * @param      PropelPDO $con
     * @param      String    $join_behavior the type of joins to use, defaults to Criteria::LEFT_JOIN
     * @return array           Array of ClTransferencia objects.
     * @throws PropelException Any exceptions caught during processing will be
     *		 rethrown wrapped into a PropelException.
     */
    public static function doSelectJoinClEstadoTransferencia(Criteria $criteria, $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        $criteria = clone $criteria;

        // Set the correct dbName if it has not been overridden
        if ($criteria->getDbName() == Propel::getDefaultDB()) {
            $criteria->setDbName(ClTransferenciaPeer::DATABASE_NAME);
        }

        ClTransferenciaPeer::addSelectColumns($criteria);
        $startcol = ClTransferenciaPeer::NUM_HYDRATE_COLUMNS;
        ClEstadoTransferenciaPeer::addSelectColumns($criteria);

        $criteria->addJoin(ClTransferenciaPeer::CLESTADOTRANSFERENCIA_ID, ClEstadoTransferenciaPeer::CLESTADOTRANSFERENCIA_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseClTransferenciaPeer', $criteria, $con);
        }

        $stmt = BasePeer::doSelect($criteria, $con);
        $results = array();

        while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $key1 = ClTransferenciaPeer::getPrimaryKeyHashFromRow($row, 0);
            if (null !== ($obj1 = ClTransferenciaPeer::getInstanceFromPool($key1))) {
                // We no longer rehydrate the object, since this can cause data loss.
                // See http://www.propelorm.org/ticket/509
                // $obj1->hydrate($row, 0, true); // rehydrate
            } else {

                $cls = ClTransferenciaPeer::getOMClass();

                $obj1 = new $cls();
                $obj1->hydrate($row);
                ClTransferenciaPeer::addInstanceToPool($obj1, $key1);
            } // if $obj1 already loaded

            $key2 = ClEstadoTransferenciaPeer::getPrimaryKeyHashFromRow($row, $startcol);
            if ($key2 !== null) {
                $obj2 = ClEstadoTransferenciaPeer::getInstanceFromPool($key2);
                if (!$obj2) {

                    $cls = ClEstadoTransferenciaPeer::getOMClass();

                    $obj2 = new $cls();
                    $obj2->hydrate($row, $startcol);
                    ClEstadoTransferenciaPeer::addInstanceToPool($obj2, $key2);
                } // if obj2 already loaded

                // Add the $obj1 (ClTransferencia) to $obj2 (ClEstadoTransferencia)
                $obj2->addClTransferencia($obj1);

            } // if joined row was not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }


