    /**
     * Returns the number of rows matching criteria, joining all related tables
     *
     * @param      Criteria $criteria
     * @param      boolean $distinct Whether to select only distinct columns; deprecated: use Criteria->setDistinct() instead.
     * @param      PropelPDO $con
     * @param      String    $join_behavior the type of joins to use, defaults to Criteria::LEFT_JOIN
     * @return int Number of matching rows.
     */
    public static function doCountJoinAll(Criteria $criteria, $distinct = false, PropelPDO $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        // we're going to modify criteria, so copy it first
        $criteria = clone $criteria;

        // We need to set the primary table name, since in the case that there are no WHERE columns
        // it will be impossible for the BasePeer::createSelectSql() method to determine which
        // tables go into the FROM clause.
        $criteria->setPrimaryTableName(ClTransferenciaPeer::TABLE_NAME);

        if ($distinct && !in_array(Criteria::DISTINCT, $criteria->getSelectModifiers())) {
            $criteria->setDistinct();
        }

        if (!$criteria->hasSelectClause()) {
            ClTransferenciaPeer::addSelectColumns($criteria);
        }

        $criteria->clearOrderByColumns(); // ORDER BY won't ever affect the count

        // Set the correct dbName
        $criteria->setDbName(ClTransferenciaPeer::DATABASE_NAME);

        if ($con === null) {
            $con = Propel::getConnection(ClTransferenciaPeer::DATABASE_NAME, Propel::CONNECTION_READ);
        }

        $criteria->addJoin(ClTransferenciaPeer::CLESTADOTRANSFERENCIA_ID, ClEstadoTransferenciaPeer::CLESTADOTRANSFERENCIA_ID, $join_behavior);

        $criteria->addJoin(ClTransferenciaPeer::COMINTERNA_ID, ComInternaPeer::COMINTERNA_ID, $join_behavior);

        $criteria->addJoin(ClTransferenciaPeer::COMRECIBIDA_ID, ComRecibidaPeer::COMRECIBIDA_ID, $join_behavior);

        $criteria->addJoin(ClTransferenciaPeer::CLIENTE_ID, ClientePeer::CLIENTE_ID, $join_behavior);

        $criteria->addJoin(ClTransferenciaPeer::COMENVIADA_ID, ComEnviadaPeer::COMENVIADA_ID, $join_behavior);

        $criteria->addJoin(ClTransferenciaPeer::CLORIGENTRANSFERENCIA_ID, ClOrigenTransferenciaPeer::CLORIGENTRANSFERENCIA_ID, $join_behavior);

        $criteria->addJoin(ClTransferenciaPeer::CLDESTINOTRANSFERENCIA_ID, ClDestinoTransferenciaPeer::CLDESTINOTRANSFERENCIA_ID, $join_behavior);

        $criteria->addJoin(ClTransferenciaPeer::TIPODOCUMENTAL_ID, TipoDocumentalPeer::TIPODOCUMENTAL_ID, $join_behavior);

        $criteria->addJoin(ClTransferenciaPeer::DOCUMENTACION_ID, DocumentacionPeer::DOCUMENTACION_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseClTransferenciaPeer', $criteria, $con);
        }

        $stmt = BasePeer::doCount($criteria, $con);

        if ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $count = (int) $row[0];
        } else {
            $count = 0; // no rows returned; we infer that means 0 matches.
        }
        $stmt->closeCursor();

        return $count;
    }

